import { Component, h, Prop, Event, EventEmitter, Element, State, Host, Listen } from '@stencil/core';
import classnames from 'classnames';
import { SvgCheck, SvgCheckIndeterminate } from './SvgCheck';
import { CheckboxGroupContext, CheckboxGroupContextValue } from '@src/components/ks-checkbox-group/context';
import { Slot, Slots, Uncontrollable, Vue2ValueFix } from '@src/framework/decorators';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { FormContextValueReconcile } from '@src/components/ks-form/utils';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { Consume } from '@src/framework/runtime-context';
import { Status } from '@src/shared/base-props';
import { KsIconHelp } from '@fe-infra/keystone-icons-stencil';

const prefix = 'checkbox';

/**
 * @slot default - Label or custom content rendered inside the checkbox label.
 * @slot prefix - The slot for the prefix.
 * @slot suffix - The slot for the suffix.
 * @slot description - The slot for providing descriptive text for the checkbox. Appears under the checkbox label.
 * @slot descriptionBelow - The slot for providing long descriptive text for the checkbox. Appears under the whole checkbox.
 * @slot helpContent - The slot for the help content inside the tooltip icon.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-checkbox',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsCheckbox extends FormBaseComponent<boolean> {
  static vModel = { prop: 'checked', event: 'ksChange' };
  @Element() el!: HTMLKsCheckboxElement;

  @Consume({
    context: CheckboxGroupContext,
    subscribe: true,
  })
  @State()
  checkboxGroupContext?: CheckboxGroupContextValue;

  /** Determine whether the checkbox is disabled. When set to `true`, the checkbox cannot be interacted with by the user. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** The status of the checkbox. Can be one of the following values: `success`, `error`, `warning`, `default`. */
  @Prop() @FormContextValueReconcile() status?: Status;
  /** Indicate whether the checkbox is currently checked. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) checked?: boolean;
  /** Set the initial checked state of the checkbox when the component is first rendered. This does not change after the initial render. */
  @Prop() defaultChecked?: boolean;
  @Uncontrollable('checked', 'defaultChecked', 'ksChange') @State() internalCheckedState?: boolean;
  /** Whether the checkbox should receive focus on render. */
  @Prop() autoFocus?: boolean;
  /** Indicate whether the checkbox is in an indeterminate state. If `true`, the checkbox appears in a partially checked state, typically used for representing a mixed selection. */
  @Prop() indeterminate?: boolean;
  /** Controls the size of the checkbox. Can be one of the following values: `md`, `sm`. */
  @Prop() size: 'md' | 'sm' = 'md';
  /** The value associated with the checkbox. This is the data that will be returned when the checkbox is checked. It is used to identify the checkbox in the context of the form or group. */
  @Prop() @Vue2ValueFix() value?: string | number;
  /** Whether to force the checkbox to ignore the KsCheckboxGroup management. If set to `true`, the checkbox's checked state can be independently controlled, even if it is nested within a KsCheckboxGroup. */
  @Prop() forceIgnoreGroup = false;
  /** Custom event triggered when the checked state of the checkbox changes. It returns the new value of the checkbox, allowing the parent component to react to the change. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<boolean>; // 禁止冒泡，防止事件冒泡到group组件的valuechange事件
  @Listen('ksChange')
  onKsChange(event: CustomEvent<boolean>) {
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value: event.detail } });
    this.checkboxGroupContext?.onValueChange?.(this.value || '');

    // FIXME: stencil extend does not support 2 listener on same event
    this.onKsChangeForForm(event);
  }

  /** The default slot for the label of the checkbox. */
  @Slot({ slotname: '_default' }) private defaultSlot?: Slots;
  /** The slot for the prefix of the checkbox. */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;
  /** The slot for the suffix of the checkbox. */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;
  /** The slot for the description of the checkbox. */
  @Slot({ slotname: 'description' }) private descriptionSlots?: Slots;
  /** The slot for the description of the checkbox. */
  @Slot({ slotname: 'descriptionBelow' }) private descriptionBelowSlots?: Slots;
  /** The slot for the help content inside the tooltip icon */
  @Slot({ slotname: 'helpContent' }) private helpContentSlot?: Slots;

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  get resolvedDisabled() {
    return (!this.forceIgnoreGroup && this.checkboxGroupContext?.disabled) || this.disabled;
  }

  private handleValueChange = (event: Event) => {
    if (this.resolvedDisabled) {
      return;
    }
    const value = (event.target as HTMLInputElement).checked;
    this.internalCheckedState = value;
  };

  private stopPropagation(event: Event) {
    event.stopPropagation();
  }

  private get hasDefaultSlotContent() {
    return (
      Boolean(this.defaultSlot?.length) ||
      Array.from(this.el.childNodes).some(
        (node) => node.nodeType === Node.TEXT_NODE && Boolean(node.textContent?.trim()),
      )
    );
  }

  render() {
    const checked =
      this.checkboxGroupContext?.value !== undefined && !this.forceIgnoreGroup
        ? this.checkboxGroupContext.value.includes(this.value || '')
        : this.internalCheckedState;
    const displayClassPrefix = `${prefix}__display`;
    const hasContent = this.hasDefaultSlotContent || this.descriptionSlots || this.helpContentSlot || this.suffixSlot;
    const classes = classnames(`${prefix}`, `${prefix}--${this.size}`, {
      [`${prefix}--disabled`]: this.resolvedDisabled,
      [`${prefix}--checked`]: checked,
      [`${prefix}--${this.status}`]: this.status,
      [`${prefix}--indeterminate`]: this.indeterminate,
      [`${prefix}--start`]: this.descriptionSlots,
    });
    return (
      <Host
        class="KsCheckbox"
        role="checkbox"
        aria-checked={this.indeterminate && this.internalCheckedState ? 'mixed' : `${this.internalCheckedState}`}
      >
        <div class={classes} part="base" data-testid="ks-checkbox-index-suhFTn">
          <div class={`${prefix}__control`}>
            <span class={`${displayClassPrefix}`} data-testid="ks-checkbox-index-8veYVr">
              <input
                id="checkbox"
                onChange={this.handleValueChange}
                class={`${prefix}__input`}
                type="checkbox"
                name={this.checkboxGroupContext?.htmlName}
                disabled={this.resolvedDisabled}
                autofocus={this.autoFocus}
                checked={checked}
                data-testid="ks-checkbox-index-hCMjrk"
              />
              {checked && !this.indeterminate && <SvgCheck className={`${`${displayClassPrefix}`}__icon`} />}
              {this.indeterminate && <SvgCheckIndeterminate className={`${`${displayClassPrefix}`}__icon`} />}
            </span>
            {this.prefixSlot && <slot name="prefix" />}
          </div>

          {hasContent && (
            <div class={`${prefix}__content`}>
              <div class={`${prefix}__content__header`}>
                <label
                  class={`${prefix}__label`}
                  htmlFor="checkbox"
                  onClick={this.stopPropagation}
                  data-testid="ks-checkbox-index-3WfYsv"
                >
                  <slot />
                </label>
                {this.helpContentSlot && (
                  <ks-tooltip size={this.size}>
                    <KsIconHelp style={{ color: 'var(--ks-color-neutral-lowOnSurface)' }} />
                    <slot name="helpContent" slot="content" />
                  </ks-tooltip>
                )}
                {this.suffixSlot && <slot name="suffix" />}
              </div>
              {this.descriptionSlots && (
                <div class={`${prefix}__description`}>
                  <slot name="description" />
                </div>
              )}
            </div>
          )}
        </div>
        {this.descriptionBelowSlots && (
          <div class={classnames(`${prefix}__description`, `${prefix}__description--below`)}>
            <slot name="descriptionBelow" />
          </div>
        )}
      </Host>
    );
  }
}
